Last-write-wins per bucket key.
   * Accepts both the literal `rate_limit_info` payload and a wrapping object;
   * callers should pass the inner info.

CREATE TRIGGER IF NOT EXISTS trg_memory_items_fts_delete
    AFTER DELETE ON memory_items
    BEGIN
      DELETE FROM memory_items_fts WHERE memory_item_id = old.id;
    END;
